-- TPC-DS Test_Query Query 104
-- Based on: query13.tpl (medium)
-- Variation: 50

select avg(ss_quantity) ,avg(ss_ext_sales_price) ,avg(ss_ext_wholesale_cost) ,sum(ss_ext_wholesale_cost) from store_sales ,store ,customer_demographics ,household_demographics ,customer_address ,date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 1954 and((ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.3' and cd_education_status = 'ES.1' and ss_sales_price between 100.1 and 150.1 and hd_dep_count = 2 )or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.2' and ss_sales_price between 50.1 and 100.1 and hd_dep_count = 2 ) or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.3' and cd_education_status = 'ES.5' and ss_sales_price between 150.1 and 200.2 and hd_dep_count = 1 )) and((ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.2', 'STATE.4', 'STATE.1') and ss_net_profit between 102 and 208 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.2', 'STATE.3', 'STATE.5') and ss_net_profit between 157 and 304 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.7', 'STATE.10', 'STATE.9') and ss_net_profit between 51 and 241 ));
